import time
from typing import Optional

from gwlib.metrics import Metrics
from gwlib.router import Router
from gwlib.request import Request
from gwlib.response import Response
from gwlib.clock import Clock


class Gateway:
    def __init__(self, router: Router, metrics: Metrics, clock: Clock, limiter: Optional[object] = None):
        self.router = router
        self.metrics = metrics
        self.clock = clock
        self.limiter = limiter

    def dispatch(self, request: Request) -> Response:
        route = self.router.route(request)
        if route is None:
            return Response(404, "not found")

        # Count the call
        self.metrics.increment(f"route.{route.name}.calls")

        # Rate limiting check
        if self.limiter is not None:
            if not self.limiter.check(request.client):
                self.metrics.increment(f"route.{route.name}.limited")
                return Response(429, "rate limited")

        # Proceed with handler
        try:
            result = route.handler(request)
            self.metrics.increment(f"route.{route.name}.ok")
            return Response(200, result)
        except Exception as e:
            self.metrics.increment(f"route.{route.name}.error")
            return Response(500, str(e))
